# -*- coding: utf-8 -*-
"""
MANAPRINT — Générateur AHE (création RANIHEI)
=============================================
Le dessin est LA MAQUETTE DE RANIHEI, relevée trait pour trait. On n'y
ajoute que deux choses : les TROIS NUMÉROS dans les trois perles, et le
NUMÉRO DE SÉRIE dans la pastille prévue pour lui.

⚠️⚠️ RÈGLE ABSOLUE (sceau Maeva) : ON NE TOUCHE PAS AU DESSIN.
   Il n'a pas été redessiné ni « amélioré » : il a été tracé depuis son
   fichier. Coquille, perles, atolls, palmiers, oiseaux, pirogue, fleurs
   d'hibiscus, frise du cadre, titre AHE, nom de la boutique et numéro
   de téléphone — tout vient d'elle et rien n'a été retouché.
   La SEULE chose effacée du fichier d'origine : les chiffres « 001 »
   de la pastille SÉRIE N°, puisqu'ils changent à chaque carton.

⚠️ 23/09, 20h05 : RANIHEI a fourni une DEUXIÈME maquette, presque carrée,
   posée par 6 sur la feuille. C'est celle-ci qui est tracée ici. La
   première (format allongé, 1536 × 1024) est abandonnée — ne pas la
   remettre.

LES TROIS PERLES (sceau Maeva 23/09) :
   perle de GAUCHE  → les plages du B   :  1 à 15
   perle du MILIEU  → les plages du I   : 16 à 30
   perle de DROITE  →                     76 à 90

Jeu EXCLUSIF de l'enseigne RANIHEI SISTERS & SHOP.
"""
import io
import random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4
from reportlab.lib import colors
from reportlab.lib.units import mm
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
import os as _osA

# SÉCURITÉ ANTI-PHOTOCOPIE — anti-panne : sans le module, les cartons
# sortent normalement, simplement sans microtexte.
try:
    from generators import securite as _sec
except Exception:
    try:
        import securite as _sec
    except Exception:
        _sec = None

try:
    pdfmetrics.registerFont(TTFont("DJL", "/usr/share/fonts/truetype/dejavu/DejaVuSans-ExtraLight.ttf"))
    POLICE = "DJL"
except Exception:
    POLICE = "Helvetica"

# ── L'ÉCRITURE DES CHIFFRES : la même que les OHANA 75 ────────────────
from reportlab.pdfbase import pdfmetrics as _pm
from reportlab.pdfbase.ttfonts import TTFont as _TF
_POLICE_ECO = "Helvetica"
try:
    _pm.registerFont(_TF("DJLECO", "/usr/share/fonts/truetype/dejavu/DejaVuSans-ExtraLight.ttf"))
    _POLICE_ECO = "DJLECO"
except Exception:
    pass
try:
    _pm.registerFont(_TF("LMROMAN", _osA.path.join(
        _osA.path.dirname(_osA.path.abspath(__file__)), "LatinModern.ttf")))
    _POLICE_ECO = "LMROMAN"
except Exception:
    pass
_GRIS_ECO = colors.Color(0.26, 0.26, 0.26)
# ⚠️ même gras que les OHANA 75 (sceau Maeva 23/09) : c'est le CONTOUR du
#    chiffre qui s'épaissit, jamais la police. Voir securite._form_chiffre.
_GRAS_TRAIT = 0.026
_POLICE_P15 = _POLICE_ECO
_GRIS_P15 = colors.Color(0.14, 0.14, 0.14)


def _style_chiffres(style):
    """Retourne (police, gris) des chiffres selon la gamme choisie."""
    if str(style).lower() in ("p15", "premium"):
        return _POLICE_P15, _GRIS_P15
    return _POLICE_ECO, _GRIS_ECO


# ══ LA MAQUETTE DE RANIHEI ═══════════════════════════════════════════
# Dimensions du carton relevé sur sa planche de 6. Tout le reste est en
# MILLIÈMES de ces deux nombres : le carton peut grandir ou rétrécir, le
# dessin ne se déforme jamais.
MAQ_W, MAQ_H = 486.0, 470.0

# Les trois perles : x, y, rayon — en millièmes, relevés sur SON dessin.
# ⚠️ Chaque point a été choisi ainsi : on mesure la distance de chaque
#    point blanc au trait le plus proche, on garde ceux qui conservent au
#    moins 88 % du dégagement maximal, et parmi eux le plus proche du
#    centre visuel de la perle. Le chiffre est donc centré à l'œil ET ne
#    touche jamais un trait de RANIHEI.
# ⚠️ L'ORDRE EST CELUI DE LA LECTURE : gauche, milieu, droite.
PERLES = [
    (333.3, 525.5, 57.1),    # 1re perle — plages du B  :  1-15
    (491.8, 589.4, 70.8),    # 2e  perle — plages du I  : 16-30
    (650.2, 525.5, 70.3),    # 3e  perle —                76-90
]
PLAGES = [(1, 15), (16, 30), (76, 90)]

# ⭐⭐ La taille des chiffres dans les perles (sceau Maeva 23/09, 20h18).
# ⚠️⚠️ 30 pt EST LE MAXIMUM, ET IL A ÉTÉ MESURÉ, PAS CALCULÉ.
#    On a imprimé à 400 puis 600 dpi CHAQUE valeur possible de chaque
#    plage, taille par taille, et compté les pixels où le chiffre touche
#    un trait de RANIHEI :
#       30 pt → aucun contact
#       31 pt → 19 pixels dans la perle de GAUCHE
#    C'est donc la perle de gauche qui commande (celle du milieu la
#    recouvre en partie). Le milieu tiendrait 37 pt, la droite 38.
#    ⚠️ NE PAS MONTER AU-DESSUS DE 30 sans refaire cette mesure : le
#    calcul géométrique seul est trompeur ici. Il donnait 23 pt comme
#    maximum parce qu'il inscrit un CERCLE dans la perle ; or la perle a
#    des coins que ce cercle n'atteint pas, et le chiffre, lui, les
#    utilise. Sept points de lisibilité étaient perdus pour rien.
_T_PERLE = 30.0

# La pastille SÉRIE N° : à la place EXACTE des « 001 » effacés.
#   SERIE_X    : le milieu des chiffres effacés
#   SERIE_BASE : leur ligne de pied (drawCentredString se cale dessus)
#   SERIE_PT   : leur hauteur d'origine convertie en corps de police
SERIE_X = 869.3
SERIE_BASE = 119.1
SERIE_PT = 53.2


